function(container, apiUrl, tables) {
  const resultTbody = container.querySelector("#result-tbody");
  const resultCount = container.querySelector("#result-count");
  const detailPanel = container.querySelector("#detail-panel");
  const detailEmpty = container.querySelector("#detail-empty");
  const detailTitle = container.querySelector("#detail-title");
  const detailSubtitle = container.querySelector("#detail-subtitle");
  const timelineContainer = container.querySelector("#timeline-container");

  // 1. 再描画関数
  function renderRows(rows) {
    resultTbody.innerHTML = rows.map(r => {
      const resourceName = r.契約書名 || r.提案資料名 || r.資料名 || "無名";
      const type = r.契約種別 || r.ステータス === "下書き" ? "提案資料" : "契約書";
      const status = r.ステータス || "-";
      const createdDate = r.作成日時 ? new Date(r.作成日時).toLocaleDateString("ja-JP") : "-";

      return `
        <tr data-id="${r.id || r.契約書ID || r.提案資料ID}" data-record='${JSON.stringify(r)}' style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 10px 12px; color: var(--text);">${resourceName}</td>
          <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px;">${type}</td>
          <td style="padding: 10px 12px;">
            <span style="padding: 3px 8px; border-radius: 3px; font-size: 11px; font-weight: 600; background: ${getStatusBg(status)}; color: ${getStatusColor(status)};">
              ${status}
            </span>
          </td>
          <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px;">${createdDate}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="view-detail-btn" data-id="${r.id || r.契約書ID || r.提案資料ID}" style="padding: 4px 10px; font-size: 11px; background: var(--primary); color: #fff; border: none; border-radius: 3px; cursor: pointer; font-weight: 600;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");
    resultCount.textContent = rows.length;
  }

  function getStatusBg(status) {
    const map = {
      "草案": "rgba(139,0,0,0.2)",
      "承認待ち": "rgba(255,165,0,0.2)",
      "有効": "rgba(0,128,0,0.2)",
      "終了": "rgba(128,128,128,0.2)",
      "下書き": "rgba(139,0,0,0.2)",
      "提案中": "rgba(255,165,0,0.2)",
      "契約済み": "rgba(0,128,0,0.2)",
      "却下": "rgba(255,0,0,0.2)"
    };
    return map[status] || "rgba(128,128,128,0.2)";
  }

  function getStatusColor(status) {
    const map = {
      "草案": "#ffb3b3",
      "承認待ち": "#ffd699",
      "有効": "#99ff99",
      "終了": "#cccccc",
      "下書き": "#ffb3b3",
      "提案中": "#ffd699",
      "契約済み": "#99ff99",
      "却下": "#ff9999"
    };
    return map[status] || "#cccccc";
  }

  // 2. 初期データ描画
  const allRecords = tables[0]?.records || [];
  renderRows(allRecords);

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const type = container.querySelector("#select-type").value;
    const status = container.querySelector("#select-status").value;
    const creator = container.querySelector("#select-creator").value;
    const createdFrom = container.querySelector("#input-created-from").value;

    const filtered = allRecords.filter(r => {
      const name = (r.契約書名 || r.提案資料名 || r.資料名 || "").toLowerCase();
      const rType = r.契約種別 || (r.ステータス === "下書き" ? "提案資料" : "契約書");
      const rStatus = r.ステータス || "";
      const rCreator = r.作成者 || "";
      const rCreated = r.作成日時 ? new Date(r.作成日時).toISOString().split("T")[0] : "";

      const matchKeyword = !keyword || name.includes(keyword) || JSON.stringify(r).toLowerCase().includes(keyword);
      const matchType = !type || rType === type;
      const matchStatus = !status || rStatus === status;
      const matchCreator = !creator || rCreator === creator;
      const matchDate = !createdFrom || rCreated >= createdFrom;

      return matchKeyword && matchType && matchStatus && matchCreator && matchDate;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-keyword").value = "";
    container.querySelector("#select-type").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#select-creator").value = "";
    container.querySelector("#input-created-from").value = "";
    renderRows(allRecords);
  });

  // 5. 詳細表示（行クリック）
  container.addEventListener("click", (e) => {
    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      const row = e.target.closest("tr");
      const record = JSON.parse(row.dataset.record);
      showDetail(record);
    }
  });

  function showDetail(record) {
    const resourceName = record.契約書名 || record.提案資料名 || record.資料名 || "無名";
    const type = record.契約種別 || (record.ステータス === "下書き" ? "提案資料" : "契約書");
    const status = record.ステータス || "-";
    const creator = record.作成者 || record.作成者ID || "-";
    const created = record.作成日時 ? new Date(record.作成日時).toLocaleString("ja-JP") : "-";
    const updated = record.更新日時 ? new Date(record.更新日時).toLocaleString("ja-JP") : "-";
    const description = record.契約書説明 || record.説明 || "説明なし";

    detailTitle.textContent = resourceName;
    detailSubtitle.textContent = `${type} • ${status}`;
    container.querySelector("#detail-id").textContent = record.id || record.契約書ID || record.提案資料ID || "-";
    container.querySelector("#detail-type").textContent = type;
    container.querySelector("#detail-status").textContent = status;
    container.querySelector("#detail-creator").textContent = creator;
    container.querySelector("#detail-created").textContent = created;
    container.querySelector("#detail-updated").textContent = updated;
    container.querySelector("#detail-description").textContent = description;

    // 変更履歴タイムライン（ダミー）
    timelineContainer.innerHTML = `
      <div style="padding: 10px; border-left: 2px solid #ffd700; background: rgba(255,215,0,0.1); border-radius: 3px;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 3px;">ステータス変更</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 3px;">草案 → 承認待ち</div>
        <div style="font-size: 11px; color: var(--text-muted);">2024-01-15 14:30</div>
      </div>
      <div style="padding: 10px; border-left: 2px solid #ffd700; background: rgba(255,215,0,0.1); border-radius: 3px;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 3px;">内容更新</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 3px;">契約金額: 1,000,000 → 1,200,000</div>
        <div style="font-size: 11px; color: var(--text-muted);">2024-01-10 09:15</div>
      </div>
      <div style="padding: 10px; border-left: 2px solid #ffd700; background: rgba(255,215,0,0.1); border-radius: 3px;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 3px;">作成</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 3px;">初版作成</div>
        <div style="font-size: 11px; color: var(--text-muted);">2024-01-05 10:00</div>
      </div>
    `;

    detailPanel.style.display = "block";
    detailEmpty.style.display = "none";
  }

  // 6. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = Array.from(resultTbody.querySelectorAll("tr")).map(tr => JSON.parse(tr.dataset.record));
    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["資料名", "種別", "ステータス", "作成者", "作成日", "説明"];
    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => {
        const name = r.契約書名 || r.提案資料名 || r.資料名 || "";
        const type = r.契約種別 || (r.ステータス === "下書き" ? "提案資料" : "契約書");
        const status = r.ステータス || "";
        const creator = r.作成者 || "";
        const created = r.作成日時 ? new Date(r.作成日時).toLocaleDateString("ja-JP") : "";
        const desc = (r.契約書説明 || r.説明 || "").replace(/"/g, '""');
        return [name, type, status, creator, created, desc].map(v => `"${v}"`).join(",");
      })
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "contract_proposal_export.csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const invoiceTableIndex = 0;  // 請求書テーブル
  const emailTableIndex = 1;    // メール履歴テーブル

  // 初期データ
  let allInvoices = (tables[invoiceTableIndex]?.records || []);
  let allEmails = (tables[emailTableIndex]?.records || []);
  let selectedInvoiceId = null;

  // ===== 1. 請求書一覧の再描画 =====
  function renderInvoices(invoices) {
    const tbody = container.querySelector("#invoice-tbody");
    tbody.innerHTML = invoices.map(inv => {
      const statusColor = inv.請求ステータス === "支払済" ? "#4ade80" : 
                          inv.請求ステータス === "期限超過" ? "#ef4444" : 
                          inv.請求ステータス === "送付済" ? "#60a5fa" : "#9ca3af";
      return `
        <tr data-id="${inv.請求書ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${inv.請求書番号 || ""}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text-muted); font-size: 0.8125rem;">${inv.請求日 ? new Date(inv.請求日).toLocaleDateString("ja-JP") : ""}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: right; color: var(--text); font-weight: 600;">¥${(inv.請求金額合計 || 0).toLocaleString()}</td>
          <td style="padding: 0.5rem 0.75rem;"><span style="display: inline-block; padding: 0.25rem 0.5rem; background: ${statusColor}20; color: ${statusColor}; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 600;">${inv.請求ステータス || ""}</span></td>
        </tr>
      `;
    }).join("");

    // 行クリックで選択
    tbody.querySelectorAll("tr").forEach(row => {
      row.addEventListener("click", () => {
        tbody.querySelectorAll("tr").forEach(r => r.style.background = "");
        row.style.background = "rgba(255,255,255,0.08)";
        selectedInvoiceId = row.dataset.id;
        renderEmailTimeline();
      });
    });
  }

  // ===== 2. メール履歴タイムラインの再描画 =====
  function renderEmailTimeline() {
    const timeline = container.querySelector("#email-timeline");

    if (!selectedInvoiceId) {
      timeline.innerHTML = `<p style="color: var(--text-muted); font-size: 0.875rem; text-align: center; padding: 2rem 0;">請求書を選択してください</p>`;
      return;
    }

    const relatedEmails = allEmails.filter(e => e.請求書ID === selectedInvoiceId);

    if (relatedEmails.length === 0) {
      timeline.innerHTML = `<p style="color: var(--text-muted); font-size: 0.875rem; text-align: center; padding: 2rem 0;">関連メールはありません</p>`;
      return;
    }

    timeline.innerHTML = relatedEmails.map(email => {
      const isOutgoing = email.送受信区分 === "送信";
      const typeColor = email.メール種別 === "請求書送付" ? "#f59e0b" :
                        email.メール種別 === "支払確認" ? "#10b981" :
                        email.メール種別 === "契約確認" ? "#3b82f6" : "#8b5cf6";
      return `
        <div style="padding: 0.75rem; background: rgba(255,255,255,0.03); border-left: 3px solid ${typeColor}; border-radius: 0.375rem;">
          <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 0.5rem;">
            <div>
              <p style="font-size: 0.8125rem; color: var(--text-muted); margin: 0 0 0.25rem 0;">
                <strong style="color: var(--text);">${isOutgoing ? "送信" : "受信"}</strong> • ${email.メール種別}
              </p>
              <p style="font-size: 0.875rem; color: var(--text); margin: 0; font-weight: 500;">${email.件名 || "(件名なし)"}</p>
            </div>
            <span style="font-size: 0.75rem; color: var(--text-muted);">${email.送受信日時 ? new Date(email.送受信日時).toLocaleDateString("ja-JP") : ""}</span>
          </div>
          <p style="font-size: 0.8125rem; color: var(--text-muted); margin: 0.5rem 0 0 0;">
            ${isOutgoing ? "送信者" : "受信者"}: <span style="color: var(--text);">${email.送信者メールアドレス || email.受信者メールアドレス}</span>
          </p>
          ${email.添付ファイル有無 ? `<p style="font-size: 0.75rem; color: #f59e0b; margin: 0.25rem 0 0 0;">📎 添付ファイルあり</p>` : ""}
        </div>
      `;
    }).join("");
  }

  // ===== 3. フィルタリング関数 =====
  function applyFilters() {
    const customerFilter = container.querySelector("#filter-customer").value;
    const contractFilter = container.querySelector("#filter-contract").value;
    const statusFilter = container.querySelector("#filter-invoice-status").value;
    const dateFromFilter = container.querySelector("#filter-invoice-date-from").value;
    const dateToFilter = container.querySelector("#filter-invoice-date-to").value;
    const amountMinFilter = parseFloat(container.querySelector("#filter-amount-min").value) || 0;
    const amountMaxFilter = parseFloat(container.querySelector("#filter-amount-max").value) || Infinity;

    const filtered = allInvoices.filter(inv => {
      if (customerFilter && inv.顧客企業ID !== customerFilter) return false;
      if (contractFilter && inv.契約ID !== contractFilter) return false;
      if (statusFilter && inv.請求ステータス !== statusFilter) return false;
      if (dateFromFilter && new Date(inv.請求日) < new Date(dateFromFilter)) return false;
      if (dateToFilter && new Date(inv.請求日) > new Date(dateToFilter)) return false;
      if (inv.請求金額合計 < amountMinFilter || inv.請求金額合計 > amountMaxFilter) return false;
      return true;
    });

    renderInvoices(filtered);
    selectedInvoiceId = null;
    renderEmailTimeline();
  }

  // ===== 4. イベントリスナー登録 =====
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-customer").value = "";
    container.querySelector("#filter-contract").value = "";
    container.querySelector("#filter-invoice-status").value = "";
    container.querySelector("#filter-invoice-date-from").value = "";
    container.querySelector("#filter-invoice-date-to").value = "";
    container.querySelector("#filter-amount-min").value = "";
    container.querySelector("#filter-amount-max").value = "";
    container.querySelector("#filter-email-type").value = "";
    container.querySelector("#filter-sender").value = "";
    renderInvoices(allInvoices);
    selectedInvoiceId = null;
    renderEmailTimeline();
  });

  // CSV エクスポート（請求書）
  container.querySelector("#btn-export-invoice").addEventListener("click", () => {
    const rows = container.querySelectorAll("#invoice-tbody tr");
    const headers = ["請求書番号", "請求日", "金額", "ステータス"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...Array.from(rows).map(row => {
        const cells = row.querySelectorAll("td");
        return [
          cells[0].textContent,
          cells[1].textContent,
          cells[2].textContent.replace("¥", "").replace(",", ""),
          cells[3].textContent
        ].map(c => `"${c}"`).join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `invoices_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 詳細表示ボタン
  container.querySelector("#btn-view-detail").addEventListener("click", () => {
    if (!selectedInvoiceId) {
      alert("請求書を選択してください");
      return;
    }
    // 詳細画面へ遷移（契約情報詳細・変更管理画面）
    window.showScreen("scr-1781957110390");
  });

  // ダッシュボードへ戻る
  container.querySelector("#btn-back-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1781956713866");
  });

  // ===== 5. 初期描画 =====
  renderInvoices(allInvoices);
  renderEmailTimeline();
}

function(container, apiUrl, tables) {
  // ========== 1. 要素取得 ==========
  const contractSelect = container.querySelector("#contract-select");
  const invoicesList = container.querySelector("#invoices-list");
  const deliverablesList = container.querySelector("#deliverables-list");
  const customerSelect = container.querySelector("#customer-select");
  const usersList = container.querySelector("#users-list");
  const deliveryDatetime = container.querySelector("#delivery-datetime");
  const btnPreview = container.querySelector("#btn-preview");
  const btnCancel = container.querySelector("#btn-cancel");
  const btnDeliver = container.querySelector("#btn-deliver");
  const confirmDialog = container.querySelector("#confirm-dialog");
  const btnConfirmCancel = container.querySelector("#btn-confirm-cancel");
  const btnConfirmOk = container.querySelector("#btn-confirm-ok");
  const successMessage = container.querySelector("#success-message");
  const errorMessage = container.querySelector("#error-message");
  const previewSummary = container.querySelector("#preview-summary");
  const emailPreview = container.querySelector("#email-preview");

  // ========== 2. 状態管理 ==========
  let selectedInvoices = [];
  let selectedDeliverables = [];
  let selectedUsers = [];
  let selectedContract = null;
  let selectedCustomer = null;

  // ========== 3. チェックボックス更新関数 ==========
  function updateInvoiceCount() {
    const checked = Array.from(container.querySelectorAll(".invoice-checkbox:checked")).length;
    container.querySelector("#invoice-count").textContent = checked;
    selectedInvoices = Array.from(container.querySelectorAll(".invoice-checkbox:checked")).map(cb => ({
      id: cb.dataset.id,
      label: cb.parentElement.textContent.trim()
    }));
    updatePreview();
  }

  function updateDeliverableCount() {
    const checked = Array.from(container.querySelectorAll(".deliverable-checkbox:checked")).length;
    container.querySelector("#deliverable-count").textContent = checked;
    selectedDeliverables = Array.from(container.querySelectorAll(".deliverable-checkbox:checked")).map(cb => ({
      id: cb.dataset.id,
      label: cb.parentElement.textContent.trim()
    }));
    updatePreview();
  }

  function updateUserCount() {
    const checked = Array.from(container.querySelectorAll(".user-checkbox:checked")).length;
    container.querySelector("#user-count").textContent = checked;
    selectedUsers = Array.from(container.querySelectorAll(".user-checkbox:checked")).map(cb => ({
      id: cb.dataset.id,
      label: cb.parentElement.textContent.trim()
    }));
    updatePreview();
  }

  // ========== 4. プレビュー更新関数 ==========
  function updatePreview() {
    const invoiceCount = selectedInvoices.length;
    const deliverableCount = selectedDeliverables.length;
    const userCount = selectedUsers.length;

    container.querySelector("#preview-invoice-count").textContent = invoiceCount;
    container.querySelector("#preview-deliverable-count").textContent = deliverableCount;
    container.querySelector("#preview-user-count").textContent = userCount;

    // メール本文の動的生成
    const contractName = contractSelect.options[contractSelect.selectedIndex]?.text || "契約";
    const emailBody = `いつもお世話になっております。

契約「${contractName}」に関する以下のデータをポータルに掲載いたしました。
ご確認のほどよろしくお願いいたします。

【配信内容】
- 請求書: ${invoiceCount}件
${selectedInvoices.map(inv => `  • ${inv.label}`).join('\n')}
- 成果物: ${deliverableCount}件
${selectedDeliverables.map(del => `  • ${del.label}`).join('\n')}

【配信先】
${selectedUsers.map(user => `• ${user.label}`).join('\n')}

【アクセス方法】
ポータルにログインいただき、「契約・成果」メニューからご確認ください。

ご不明な点がございましたら、お気軽にお問い合わせください。

よろしくお願いいたします。`;

    container.querySelector("#email-body").textContent = emailBody;
  }

  // ========== 5. イベントリスナー登録 ==========
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("invoice-checkbox")) {
      updateInvoiceCount();
    } else if (e.target.classList.contains("deliverable-checkbox")) {
      updateDeliverableCount();
    } else if (e.target.classList.contains("user-checkbox")) {
      updateUserCount();
    }
  });

  contractSelect.addEventListener("change", (e) => {
    selectedContract = e.target.value;
    updatePreview();
  });

  customerSelect.addEventListener("change", (e) => {
    selectedCustomer = e.target.value;
  });

  // ========== 6. プレビューボタン ==========
  btnPreview.addEventListener("click", () => {
    if (!selectedContract) {
      alert("配信対象契約を選択してください");
      return;
    }
    if (selectedInvoices.length === 0 && selectedDeliverables.length === 0) {
      alert("配信対象データを選択してください");
      return;
    }
    if (selectedUsers.length === 0) {
      alert("配信対象ユーザーを選択してください");
      return;
    }
    // プレビューは既に右側に表示されているため、スクロール
    container.querySelector("#email-preview").scrollIntoView({ behavior: "smooth" });
  });

  // ========== 7. キャンセルボタン ==========
  btnCancel.addEventListener("click", () => {
    if (confirm("配信処理をキャンセルしますか？")) {
      window.showScreen("scr-1781957241812"); // ポータル配信・通知機能へ遷移
    }
  });

  // ========== 8. 配信実行ボタン ==========
  btnDeliver.addEventListener("click", () => {
    if (!selectedContract) {
      alert("配信対象契約を選択してください");
      return;
    }
    if (selectedInvoices.length === 0 && selectedDeliverables.length === 0) {
      alert("配信対象データを選択してください");
      return;
    }
    if (selectedUsers.length === 0) {
      alert("配信対象ユーザーを選択してください");
      return;
    }
    if (!deliveryDatetime.value) {
      alert("配信日時を指定してください");
      return;
    }

    // 確認ダイアログを表示
    const confirmContent = container.querySelector("#confirm-content");
    confirmContent.innerHTML = `
      <div><strong>配信対象契約:</strong> ${contractSelect.options[contractSelect.selectedIndex].text}</div>
      <div style="margin-top: 8px;"><strong>請求書:</strong> ${selectedInvoices.length}件</div>
      <div><strong>成果物:</strong> ${selectedDeliverables.length}件</div>
      <div style="margin-top: 8px;"><strong>配信先ユーザー:</strong> ${selectedUsers.length}件</div>
      <div><strong>配信日時:</strong> ${new Date(deliveryDatetime.value).toLocaleString('ja-JP')}</div>
      <div style="margin-top: 12px; padding: 8px; background: rgba(255,165,0,0.2); border-left: 3px solid #ffa500; border-radius: 3px; color: #ffa500;">
        ⚠ この操作は取り消せません。内容をご確認の上、実行してください。
      </div>
    `;
    confirmDialog.removeAttribute("hidden");
  });

  // ========== 9. 確認ダイアログのキャンセル ==========
  btnConfirmCancel.addEventListener("click", () => {
    confirmDialog.setAttribute("hidden", "");
  });

  // ========== 10. 確認ダイアログの実行 ==========
  btnConfirmOk.addEventListener("click", async () => {
    confirmDialog.setAttribute("hidden", "");

    // 配信データを構築
    const deliveryData = {
      contractId: selectedContract,
      customerId: selectedCustomer,
      invoiceIds: selectedInvoices.map(inv => inv.id),
      deliverableIds: selectedDeliverables.map(del => del.id),
      userIds: selectedUsers.map(user => user.id),
      deliveryDatetime: deliveryDatetime.value,
      createdAt: new Date().toISOString()
    };

    // API に送信（テーブルインデックス 0 を想定）
    const result = await window.aivicApi.save(0, deliveryData);

    if (result) {
      // 成功メッセージを表示
      successMessage.removeAttribute("hidden");
      setTimeout(() => {
        successMessage.setAttribute("hidden", "");
        // 配信完了後、ポータル配信・通知機能画面へ遷移
        window.showScreen("scr-1781957241812");
      }, 2000);
    } else {
      // エラーメッセージを表示
      errorMessage.removeAttribute("hidden");
      setTimeout(() => {
        errorMessage.setAttribute("hidden", "");
      }, 3000);
    }
  });

  // ========== 11. 初期化 ==========
  // デフォルト配信日時を現在時刻の1時間後に設定
  const now = new Date();
  now.setHours(now.getHours() + 1);
  deliveryDatetime.value = now.toISOString().slice(0, 16);

  updateInvoiceCount();
  updateDeliverableCount();
  updateUserCount();
}

