function(container, apiUrl, tables) {
  // テーブルインデックス（仮定: 質問・回答・資料テーブルが tables に含まれる）
  const TABLE_QUESTIONS = 0;
  const TABLE_ANSWERS = 1;
  const TABLE_EVIDENCE = 2;

  let allQuestions = [];
  let selectedQuestionId = null;
  let selectedAnswer = null;
  let uploadedEvidence = [];

  // ===== 1. 質問一覧の再描画 =====
  function renderQuestions(questions) {
    const list = container.querySelector("#questions-list");
    if (!questions || questions.length === 0) {
      list.innerHTML = '<div style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">質問がありません</div>';
      return;
    }
    list.innerHTML = questions.map(q => `
      <div 
        class="question-item" 
        data-id="${q.id}" 
        style="padding: 10px; background: var(--bg-main); border: 1px solid rgba(255,255,255,0.08); border-radius: 4px; cursor: pointer; transition: all 0.2s; margin-bottom: 8px;"
      >
        <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 4px; line-height: 1.4;">${q.質問タイトル || '無題'}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">${q.質問日 ? new Date(q.質問日).toLocaleDateString('ja-JP') : '-'}</div>
        <div style="display: flex; gap: 6px;">
          <span style="padding: 2px 6px; font-size: 10px; border-radius: 3px; background: ${q.ステータス === '回答済' ? 'rgba(76,175,80,0.2); color: #4caf50;' : 'rgba(255,165,0,0.2); color: #ffa500;'}">${q.ステータス || '未回答'}</span>
          ${q.公開ステータス === '公開' ? '<span style="padding: 2px 6px; font-size: 10px; border-radius: 3px; background: rgba(33,150,243,0.2); color: #2196f3;">公開</span>' : ''}
        </div>
      </div>
    `).join("");
  }

  // ===== 2. 質問詳細の表示 =====
  function showQuestionDetail(questionId) {
    const question = allQuestions.find(q => q.id === questionId);
    if (!question) return;

    selectedQuestionId = questionId;
    container.querySelector("#detail-question-title").textContent = question.質問タイトル || '無題';
    container.querySelector("#detail-question-text").textContent = question.質問内容 || '';
    container.querySelector("#detail-question-date").textContent = question.質問日 ? new Date(question.質問日).toLocaleDateString('ja-JP') : '-';
    container.querySelector("#detail-question-asker").textContent = question.質問者 || '-';

    const badge = container.querySelector("#detail-status-badge");
    badge.textContent = question.ステータス || '未回答';
    badge.style.background = question.ステータス === '回答済' ? 'rgba(76,175,80,0.2)' : 'rgba(255,165,0,0.2)';
    badge.style.color = question.ステータス === '回答済' ? '#4caf50' : '#ffa500';

    // 回答を取得
    const answer = tables[TABLE_ANSWERS]?.records?.find(a => a.質問ID === questionId);
    if (answer) {
      selectedAnswer = answer;
      container.querySelector("#answer-content").value = answer.回答内容 || '';
      container.querySelector("#status-value").textContent = answer.公開ステータス || '未公開';
      container.querySelector("#publish-date-value").textContent = answer.公開日時 ? new Date(answer.公開日時).toLocaleDateString('ja-JP') : '-';
    } else {
      container.querySelector("#answer-content").value = '';
      container.querySelector("#status-value").textContent = '未公開';
      container.querySelector("#publish-date-value").textContent = '-';
    }

    // 根拠資料を取得
    uploadedEvidence = (tables[TABLE_EVIDENCE]?.records || []).filter(e => e.質問ID === questionId);
    renderEvidenceList();

    // パネル表示
    container.querySelector("#question-detail-panel").style.display = 'block';
    container.querySelector("#answer-input-panel").style.display = 'block';
    container.querySelector("#evidence-panel").style.display = 'block';
    container.querySelector("#publish-status-panel").style.display = 'block';
    container.querySelector("#empty-state").style.display = 'none';
  }

  // ===== 3. 根拠資料一覧の再描画 =====
  function renderEvidenceList() {
    const list = container.querySelector("#evidence-list");
    if (!uploadedEvidence || uploadedEvidence.length === 0) {
      list.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 12px;">資料がアップロードされていません</div>';
      return;
    }
    list.innerHTML = uploadedEvidence.map(e => `
      <div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.08); display: flex; justify-content: space-between; align-items: center;">
        <div style="font-size: 12px; color: var(--text);">
          <div style="font-weight: 500; margin-bottom: 2px;">${e.ファイル名 || 'ファイル'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${e.アップロード日 ? new Date(e.アップロード日).toLocaleDateString('ja-JP') : '-'}</div>
        </div>
        <div style="display: flex; gap: 4px;">
          <button class="action-btn secondary download-evidence" data-id="${e.id}" style="padding: 4px 8px; font-size: 11px;">DL</button>
          <button class="action-btn secondary delete-evidence" data-id="${e.id}" style="padding: 4px 8px; font-size: 11px;">削除</button>
        </div>
      </div>
    `).join("");
  }

  // ===== 4. 初期データ読み込み =====
  allQuestions = tables[TABLE_QUESTIONS]?.records || [];
  renderQuestions(allQuestions);

  // ===== 5. 質問検索 =====
  container.querySelector("#question-search").addEventListener("input", (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = allQuestions.filter(q => 
      (q.質問タイトル || '').toLowerCase().includes(keyword) ||
      (q.質問内容 || '').toLowerCase().includes(keyword)
    );
    renderQuestions(filtered);
  });

  // ===== 6. 質問クリック =====
  container.addEventListener("click", (e) => {
    const item = e.target.closest(".question-item");
    if (item) {
      showQuestionDetail(item.dataset.id);
    }
  });

  // ===== 7. 回答保存 =====
  container.querySelector("#btn-save-answer").addEventListener("click", async () => {
    if (!selectedQuestionId) return;
    const content = container.querySelector("#answer-content").value.trim();
    if (!content) {
      alert("回答内容を入力してください");
      return;
    }

    const answerData = {
      質問ID: selectedQuestionId,
      回答内容: content,
      公開ステータス: '未公開',
      保存日時: new Date().toISOString()
    };

    if (selectedAnswer?.id) {
      await window.aivicApi.update(TABLE_ANSWERS, selectedAnswer.id, answerData);
    } else {
      await window.aivicApi.save(TABLE_ANSWERS, answerData);
    }

    // 再読み込み
    const updated = await window.aivicApi.list(TABLE_ANSWERS);
    if (updated) {
      selectedAnswer = updated.find(a => a.質問ID === selectedQuestionId);
      container.querySelector("#status-value").textContent = '未公開';
    }
    alert("回答を保存しました");
  });

  // ===== 8. 回答公開 =====
  container.querySelector("#btn-publish-answer").addEventListener("click", async () => {
    if (!selectedQuestionId || !selectedAnswer?.id) {
      alert("先に回答を保存してください");
      return;
    }

    await window.aivicApi.update(TABLE_ANSWERS, selectedAnswer.id, {
      公開ステータス: '公開',
      公開日時: new Date().toISOString()
    });

    container.querySelector("#status-value").textContent = '公開';
    container.querySelector("#publish-date-value").textContent = new Date().toLocaleDateString('ja-JP');
    alert("回答を公開しました");
  });

  // ===== 9. ファイルアップロード =====
  const dropzone = container.querySelector("#upload-dropzone");
  const fileInput = container.querySelector("#evidence-file-input");

  container.querySelector("#btn-select-file").addEventListener("click", () => {
    fileInput.click();
  });

  dropzone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropzone.style.background = 'rgba(255,255,255,0.08)';
  });

  dropzone.addEventListener("dragleave", () => {
    dropzone.style.background = 'transparent';
  });

  dropzone.addEventListener("drop", (e) => {
    e.preventDefault();
    dropzone.style.background = 'transparent';
    handleFiles(e.dataTransfer.files);
  });

  fileInput.addEventListener("change", (e) => {
    handleFiles(e.target.files);
  });

  async function handleFiles(files) {
    if (!selectedQuestionId) {
      alert("先に質問を選択してください");
      return;
    }

    for (const file of files) {
      const evidenceData = {
        質問ID: selectedQuestionId,
        ファイル名: file.name,
        ファイルサイズ: file.size,
        アップロード日: new Date().toISOString()
      };
      await window.aivicApi.save(TABLE_EVIDENCE, evidenceData);
    }

    const updated = await window.aivicApi.list(TABLE_EVIDENCE);
    if (updated) {
      uploadedEvidence = updated.filter(e => e.質問ID === selectedQuestionId);
      renderEvidenceList();
    }
    alert("ファイルをアップロードしました");
  }

  // ===== 10. 資料削除 =====
  container.addEventListener("click", async (e) => {
    if (e.target.closest(".delete-evidence")) {
      const id = e.target.closest(".delete-evidence").dataset.id;
      if (confirm("この資料を削除しますか？")) {
        await window.aivicApi.delete(TABLE_EVIDENCE, id);
        uploadedEvidence = uploadedEvidence.filter(e => e.id !== id);
        renderEvidenceList();
      }
    }
  });

  // ===== 11. 参照リンク =====
  const modal = container.querySelector("#reference-modal");
  const closeModal = () => { modal.style.display = 'none'; };

  container.querySelector("#btn-close-modal").addEventListener("click", closeModal);
  modal.addEventListener("click", (e) => {
    if (e.target === modal) closeModal();
  });

  container.querySelector("#btn-ref-contract").addEventListener("click", () => {
    container.querySelector("#modal-title").textContent = "契約書";
    container.querySelector("#modal-content").innerHTML = '<p>契約書の内容がここに表示されます。</p>';
    modal.style.display = 'flex';
  });

  container.querySelector("#btn-ref-proposal").addEventListener("click", () => {
    container.querySelector("#modal-title").textContent = "提案資料";
    container.querySelector("#modal-content").innerHTML = '<p>提案資料の内容がここに表示されます。</p>';
    modal.style.display = 'flex';
  });

  container.querySelector("#btn-ref-deliverable").addEventListener("click", () => {
